61	// (<AdminSubTabs />, rendered below by the layout) exposes the siblings in-page.
62	// The full membership of each group lives in lib/admin-groups.ts and is shared
63	// with the sub-tab bar so the two never drift.
64	const nav: NavSection[] = [
65	  {
66	    items: ADMIN_GROUPS.map((g) => ({
67	      label: g.label,
68	      href: g.items[0].href,
69	      icon: g.icon,
