74	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
75	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
76	  if (await adminHostBlocked()) notFound();
77	
78	  const user = await realUser();
79	  if (!user) redirect("/login");
80	  if (!isStaff(user.role)) redirect("/dashboard");
81	  const imp = await impersonating();
82	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
83	
84	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
85	  if (await adminIpBlocked()) {
86	    return (
87	      <main
88	        style={{
89	          minHeight: "100vh",
90	          display: "flex",
91	          flexDirection: "column",
92	          alignItems: "center",
93	          justifyContent: "center",
94	          gap: "0.75rem",
95	          padding: "2rem",
96	          textAlign: "center",
97	        }}
98	      >
99	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
100	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
101	          The admin console isn&apos;t available from your current network.
102	        </p>
103	      </main>
104	    );
105	  }
106	
107	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
108	  // using admin tools. Redirect (don't hard-fail) to their security settings so
109	  // they can enroll, then come back.
110	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
111	    redirect("/dashboard/settings?require2fa=1");
112	  }
113	
114	  // Hide nav items this role can't access; drop sections that end up empty.
115	  const visibleNav: NavSection[] = nav
116	    .map((section) => ({
117	      ...section,
118	      items: section.items.filter((item) => canAccessHref(user.role, item.href)),
119	    }))
120	    .filter((section) => section.items.length > 0);
121	
122	  const notifications = await db.notification.findMany({
123	    where: { userId: user.id },
124	    orderBy: { createdAt: "desc" },
125	    take: 15,
126	  });
127	
128	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
129	  // missing model/table can never break the admin layout.
130	  const soft = (p: Promise<number>) => p.catch(() => 0);
131	  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew, improvementsProposed] = await Promise.all([
132	    // Live chat: conversations flagged unread for agents (same "needs a reply"
133	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
134	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
135	    // Support desk: tickets awaiting a staff reply (open + customer replies),
136	    // matching the "Awaiting staff" stat on /admin/support.
137	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
138	    // Abuse queue: alerts still OPEN.
139	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
140	    // Feedback: new (untriaged) reports.
141	    soft(db.feedback.count({ where: { status: "NEW" } })),
142	    // Improvements board: proposals awaiting the owner's approve/decline.
143	    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
144	  ]);
145	
146	  // Per-route attention counts, unchanged in meaning from the flat sidebar.
147	  const badges: Record<string, number> = {
148	    "/admin/chat": chatUnread,
149	    "/admin/support": ticketsAwaiting,
150	    "/admin/abuse": abuseOpen,
151	    "/admin/feedback": feedbackNew,
152	    "/admin/improvements": improvementsProposed,
153	  };
154	  // Roll each group's per-route counts up onto its single top-level nav item, so
155	  // e.g. Customers shows chat+support+feedback and System shows improvements.
156	  const groupBadge: Record<string, number> = {};
157	  for (const g of ADMIN_GROUPS) {
158	    const total = g.items.reduce((n, item) => n + (badges[item.href] ?? 0), 0);
159	    if (total > 0) groupBadge[g.items[0].href] = total;
